const signedSheetMedia=new Map(),pendingMediaSigns=new Set();
function sheetMediaRef(value){return typeof value==='string'&&/^ae-media:\/\/[a-zA-Z0-9_-]{1,100}\/[0-9a-f-]{36}\.(gif|png|jpg|jpeg|webp)$/.test(value)}
