async function migrateLegacyKeys(){if(Array.isArray(db.keys))return;const old=db.keys||{},items=[];for(const [kind,name] of [['master','Mestre antigo'],['player','Jogador antigo']]){if(typeof old[kind]!=='string')continue;const salt=randomCode().replaceAll('-','');items.push({id:'legacy-'+kind,kind,name,hash:await hashKey(salt,old[kind]),salt,active:true,sheetId:kind==='player'?(db.sheets[0]?.id||''):null,demo:!db.keysChanged})}db.keys=items.length?items:clone(DEFAULT.keys);save()}

function stepDown(d){const idx=VALID_DICE.indexOf(Number(d));return idx<=0?4:VALID_DICE[idx-1]}
function randomDie(sides){const arr=new Uint32Array(1);try{crypto.getRandomValues(arr);return arr[0]%sides+1}catch(e){return Math.floor(Math.random()*sides)+1}}
function rollColorsForSkill(skill,abilityIndex){const s=db.sheets.find(x=>x.id===currentSheet);if(!s)return [];const p=sheetPalette(s.id);if(Number.isInteger(abilityIndex)){const ab=s.abilities?.[abilityIndex];if(ab)return Object.values(abilityDicePalette(s,ab))}return [p.diceGroup,p.diceSkill]}

function fichaLocalTest(s,dice){
 const c=s.combat||{},raw=dice.map(d=>({...d})),bonus=Number(c.nextBonusDie)||0;
 if([4,6,8,10,12,20].includes(bonus)){raw.push({sides:bonus,value:randomDie(bonus),bondBonus:true});c.nextBonusDie=0}
 let effect=null,active=raw;
 if(c.hollowActive){
  const n=randomDie(6);effect={mode:'hollow',sides:6,value:n,broken:n===6,advance:n===1};
  if(n===6){c.hollowActive=false;c.hollowLost=true}
  if(n===1)c.hollowProgress=Number(c.hollowProgress||0)+1;
  for(const d of raw)d.effective=d.value>n?d.sides:d.value;
 }else if([4,6,8,10,12,20].includes(Number(c.fearDie))){
  const sides=Number(c.fearDie),n=randomDie(sides);
  effect={mode:'fear',sides,value:n,cleared:n===1};
  for(const d of raw)d.effective=d.value<n?0:d.value;
  active=raw.filter(d=>d.effective>0);
  if(n===1){c.fearDie=0;s.conditions=(s.conditions||[]).filter(x=>String(x).toLowerCase()!=='amedrontado')}
 }else for(const d of raw)d.effective=d.value;
 let special='',total=raw.reduce((a,d)=>a+Number(d.effective),0);
 if(!active.length){special='FALHA CRÍTICA';total=0}
 else{special=avaliarResultadoDados(effect?.mode==='fear'?active:raw).special;if(special==='CRÍTICO')total*=2}
 s.combat=c;
 return {dice:raw,total,special,effect};
}
function formatRollEffect(r,verified){
 const parts=(r.dice||[]).map(d=>'d'+d.sides+' ('+d.value+(d.effective!==undefined&&Number(d.effective)!==Number(d.value)?' → '+d.effective:'')+')');
 const e=r.effect,info=e?(e.mode==='hollow'?'HOLLOWFICAÇÃO':'PAVOR')+' d'+e.sides+' = '+e.value+(e.broken?' · MÁSCARA ROMPIDA':'')+(e.advance?' · DOMÍNIO +1':'')+(e.cleared?' · PAVOR SUPERADO':''):'';
 return (verified?'VERIFICADA':'NÃO VERIFICADA')+' · '+parts.join(' + ')+' = '+r.total+(r.special?' · '+r.special:'')+(info?' · '+info:'');
}
async function skillRoll(skill,abilityIndex){if(!canEditSheet(currentSheet))return;
 if(window.ARQUIVO_SYNC?.state.enabled){if(rollingBusy)return;rollingBusy=true;
 try{const x=await window.ARQUIVO_SYNC.rollSkill(currentSheet,skill,Number.isInteger(abilityIndex)?abilityIndex:null);const r={id:x.id,label:x.label,total:x.total,special:x.special,dice:x.dice,
 effect:x.effect,summary:formatRollEffect(x,true)};
 r.colors=Array.isArray(x.colors)?x.colors:rollColorsForSkill(skill,abilityIndex);lastRoll=r;showRollImpact(r.special);el('rollLive').textContent=`${skill}: ${r.total}. ${r.special||'Normal'}`;
 sound('dice');if(r.special==='CRÍTICO')sound('critical');refreshRollHistorySoon();
 await window.ARQUIVO_SYNC.refresh(true);verifiedSkillRollModal(r);}catch(e){toast('Rolagem não registrada',e.message,true)}finally{rollingBusy=false;finishRollFeedback()}return;}
 const s=db.sheets.find(x=>x.id===currentSheet),g=Object.keys(GROUPS).find(g=>GROUPS[g].includes(skill));if(!s||!g)return;
 const d1=Number(s.groups[g])||4,d2=window.ARQUIVO_V3?.effectiveDie(s,skill)??(Number(s.skills[skill])||4),a=randomDie(d1),b=randomDie(d2);
 const result=fichaLocalTest(s,[{sides:d1,value:a},{sides:d2,value:b}]);window.ARQUIVO_V3?.consumeNext(s,skill);const {special,total}=result;
 const r={label:skill,total,special,dice:result.dice,effect:result.effect,summary:formatRollEffect(result,false)};
 r.colors=rollColorsForSkill(skill,abilityIndex);if(result.dice.length>2)r.colors.push('#E8C56D');save();lastRoll=r;rollHistory.unshift(r);showRollImpact(special);el('rollLive').textContent=`${skill}: ${total}. ${special||'Resultado normal'} · NÃO VERIFICADA`;
 sound('dice');if(special==='CRÍTICO')sound('critical');modal('RESULTADO NÃO VERIFICADO',rollStage(r),[]);finishRollFeedback()}

// Regra única de críticos para todas as rolagens locais. No modo online o Supabase decide.
function avaliarResultadoDados(dice){
 const faces=Array.isArray(dice)?dice:[];
 const base=faces.reduce((v,d)=>v+Number(d.value||0),0);
 const grouped=new Map();
 for(const d of faces){const v=Number(d.value);if(!grouped.has(v))grouped.set(v,[]);grouped.get(v).push(Number(d.sides||0))}
 let crit=0,fail=0;
 for(const [v,sides] of grouped){if(sides.length<2)continue;const priority=Math.max(...sides);if(v>=6)crit=Math.max(crit,priority);else if(v===1)fail=Math.max(fail,priority)}
 const special=crit>0&&crit>=fail?'CRÍTICO':fail>0?'FALHA CRÍTICA':'';
 return {base,total:special==='CRÍTICO'?base*2:base,special};
}
function updateFreeDicePreview(){
 const count=Number(el('diceCount')?.value),faces=Number(el('diceFaces')?.value),node=el('freeDicePreview');
 if(!node)return;
 const valid=Number.isInteger(count)&&count>=1&&count<=30&&Number.isInteger(faces)&&faces>=2&&faces<=1000;
 node.innerHTML=valid?'<span>PREPARADO PARA ROLAR</span><strong>'+count+'d'+faces+'</strong>':'<span>CONFIRA OS VALORES</span><strong>1 a 30 dados · 2 a 1000 faces</strong>';
}
async function freeRoll(hidden=false){
 const rawCount=Number(el(hidden?'shieldCount':'diceCount')?.value);
 const rawFaces=Number(el(hidden?'shieldFaces':'diceFaces')?.value);
 const valid=Number.isInteger(rawCount)&&rawCount>=1&&rawCount<=(hidden?12:30)&&Number.isInteger(rawFaces)&&
 (hidden?[4,6,8,10,12,20].includes(rawFaces):rawFaces>=2&&rawFaces<=1000);
 if(!valid){toast('Dados inválidos',hidden?'Use de 1 a 12 dados oficiais do Escudo.':'Escolha de 1 a 30 dados e de 2 a 1000 faces.',true);finishRollFeedback();return}
 const n=rawCount,d=rawFaces;
 if(window.ARQUIVO_SYNC?.state.enabled){if(rollingBusy)return;rollingBusy=true;
 try{const x=await window.ARQUIVO_SYNC.rollFree(n,d,hidden,Array.from({length:n},()=>hidden?currentPalette().accent:currentPalette().cold));const baseTotal=x.dice.reduce((a,v)=>a+Number(v.value),0);
 const r={label:x.label,total:x.total,special:x.special||'',dice:x.dice,summary:'VERIFICADA · '+x.dice.map(v=>v.value).join(' + ')+' = '+baseTotal+(x.special==='CRÍTICO'?' × 2 = '+x.total:'')+(x.special?' · '+x.special:'')};
 r.colors=Array.isArray(x.colors)?x.colors:[];lastRoll=r;showRollImpact(r.special);sound('dice');refreshRollHistorySoon();if(!hidden){el('rollLive').textContent='Rolagem verificada: '+r.total;const area=el('freeResult');if(area)area.innerHTML=rollStage(r)}else{const a=el('shieldResult');if(a)a.innerHTML=rollStage(r)}
 }catch(e){toast('Rolagem não registrada',e.message,true)}finally{rollingBusy=false;finishRollFeedback()}return;}
 if(hidden){toast('Escudo requer conexão online.','',true);finishRollFeedback();return}
 const dice=Array.from({length:n},()=>({sides:d,value:randomDie(d)}));
 const {base:baseTotal,special,total}=avaliarResultadoDados(dice);const critical=special==='CRÍTICO';
 const r={label:`${n}d${d}`,total,special,dice,summary:`NÃO VERIFICADA · ${dice.map(x=>x.value).join(' + ')} = ${baseTotal}${critical?' × 2 = '+total:''}${special?' · '+special:''}`};
 r.colors=dice.map(()=>currentPalette().cold);lastRoll=r;rollHistory.unshift(r);showRollImpact(special);sound('dice');el('rollLive').textContent=`Rolagem NÃO VERIFICADA: ${total}`;const area=el('freeResult');if(area)area.innerHTML=rollStage(r);finishRollFeedback()}


function reconcileRecoveryStates(s,oldResources){
 if(!s?.resources||!oldResources)return;
 const current=k=>Number(s.resources[k]?.current)||0;
 const old=k=>Number(oldResources[k])||0;
 const recoveredLife=old('vida')<=0&&current('vida')>0;
 const recoveredSoul=old('alma')<=0&&current('alma')>0;
 const recoveredStability=old('estabilidade')<=0&&current('estabilidade')>0;
 if(recoveredSoul){s.combat??={};s.combat.almaExhaustion=false}
 if((recoveredLife||recoveredSoul)&&current('vida')>0&&current('alma')>0){
  s.conditions=(s.conditions||[]).filter(c=>String(c).toLowerCase()!=='desmaiado');
 }
 if(recoveredStability&&current('estabilidade')>0){
  s.conditions=(s.conditions||[]).filter(c=>String(c).toLowerCase()!=='acorrentado');
 }
}
function resourceSetCurrent(k,value){if(!sheetPermission()||!requirePlayer())return;const s=db.sheets.find(x=>x.id===currentSheet),r=s?.resources?.[k];if(!r)return;if(!Number.isFinite(value)||value<0||value>100000000||Math.abs(value*100-Math.round(value*100))>0.00001){toast('Valor inválido','Informe valor de 0 a 100 milhões, com até duas casas decimais.',true);return}const old=Number(r.current)||0;r.current=Math.round(value*100)/100;if(old>0&&r.current===0){s.conditions??=[];s.combat??={};const stateName=k==='estabilidade'?'Acorrentado':'Desmaiado';if(!s.conditions.some(x=>String(x).toLowerCase()===stateName.toLowerCase()))s.conditions.push(stateName);if(k==='alma')s.combat.almaExhaustion=true;if(k==='vida'&&Number(s.combat.lifeSurvivals)>=3&&!s.conditions.includes('Morto'))s.conditions.push('Morto');if(k==='estabilidade'&&Number(s.combat.stabilitySurvivals)>=3)s.combat.raceStatePending=true}reconcileRecoveryStates(s,{[k]:old,vida:k==='vida'?old:s.resources.vida?.current,estabilidade:k==='estabilidade'?old:s.resources.estabilidade?.current,alma:k==='alma'?old:s.resources.alma?.current});flash=r.current<old?'damage':'heal';lastResourceId=k;save();render();if(old!==r.current)resourceLegacySound(r.current<old?'damage':'click')}
function changeResource(k,delta){const s=db.sheets.find(x=>x.id===currentSheet);if(!s?.resources?.[k])return;resourceSetCurrent(k,Math.min(100000000,Math.max(0,(Number(s.resources[k].current)||0)+delta)))}
function resourceBoundary(k,toMax){const s=db.sheets.find(x=>x.id===currentSheet);if(!s?.resources?.[k])return;resourceSetCurrent(k,toMax?Number(s.resources[k].max):0)}
function editResource(k){if(!sheetPermission()||!requirePlayer())return;const s=db.sheets.find(x=>x.id===currentSheet),r=s?.resources?.[k];if(!r)return;modal('VALOR X · '+k.toUpperCase(),`<p>Valor atual livre, inclusive decimal e acima do máximo da ficha. Valores excedentes ficam em cinza na barra.</p><div class="field"><label>Valor desejado (ex.: 27,5)<input type="text" inputmode="decimal" value="${esc(r.current)}" id="resValue" autocomplete="off"></label></div><p class="subtitle">Mínimo: 0. Máximo técnico: 100 milhões. Até 2 casas decimais.</p>`,[['SALVAR','setResource','main'],['Cancelar','closeModal']]);el('dialogRoot').dataset.resource=k}
function setResource(){if(!sheetPermission())return;const k=el('dialogRoot').dataset.resource,raw=String(el('resValue')?.value||'').trim().replace(',','.');if(!/^\d+(?:\.\d{1,2})?$/.test(raw)){toast('Valor inválido','Use um número positivo com até duas casas decimais.',true);return}const value=Number(raw);if(!Number.isFinite(value)||value>100000000){toast('Valor inválido','Limite de 100 milhões.',true);return}closeModal();resourceSetCurrent(k,value)}
async function useAbility(i){if(!sheetPermission()||!requirePlayer())return;const s=db.sheets.find(x=>x.id===currentSheet),ab=s?.abilities?.[i];if(s?.conditions?.some(c=>['desmaiado','morto'].includes(String(c).toLowerCase()))){toast('PERSONAGEM INCAPACITADO','Remova o estado Desmaiado ou Morto pelas regras antes de utilizar técnicas.',true);return}if(!ab||abilityCategory(ab)==='passive'){if(ab&&abilityCategory(ab)==='passive')toast('HABILIDADE PASSIVA','Esta habilidade não pode ser ativada.',true);return}const quote=window.ARQUIVO_V3?.costQuote(s,ab,i);
 if(quote?.blocked){toast('HABILIDADE INDISPONÍVEL',quote.reason,true);finishRollFeedback();return}
 const cost=quote?.cost??(Number(ab.cost)||0);
 const item=inventoryItemForAbility(s,ab);if(abilityCategory(ab)==='item'&&ab.inventoryItemId&&!item){toast('ITEM NÃO ENCONTRADO','O item vinculado foi removido do inventário.',true);return}if(item&&inventoryItemHasQuantity(item)&&(!Number.isInteger(Number(item.quantity))||Number(item.quantity)<1)){toast('ITEM ESGOTADO','É preciso ter ao menos uma unidade para usar esta habilidade.',true);return}if(s.resources.alma.current<cost){const node=el('ability-'+i);node?.classList.remove('shake');void node?.offsetWidth;node?.classList.add('shake');toast('ALMA INSUFICIENTE',`${ab.name} exige ${cost} de Alma.`,true);sound('damage');finishRollFeedback();return}
 const custom=abilityHasTest(ab)?abilityCustomDice(ab):null,skill=abilityHasTest(ab)&&!custom?abilityTestSkill(ab):null;
 if(window.ARQUIVO_SYNC?.state.enabled){if(rollingBusy)return;rollingBusy=true;
 try{const x=await window.ARQUIVO_SYNC.useAbility(currentSheet,i);if(x.roll){const r=x.roll;r.colors=Array.isArray(r.colors)?r.colors:[];r.summary=formatRollEffect(r,true);lastRoll=r;showRollImpact(r.special);el('rollLive').textContent=`${ab.name}: ${r.total}. ${r.special||'Normal'}`;sound((['ultimate','release','transformation'].includes(ab.category)?(ab.category==='ultimate'?'ultimate':'release'):'dice'));if(r.special==='CRÍTICO')sound('critical');refreshRollHistorySoon();modal('TÉCNICA · ROLAGEM VERIFICADA',rollStage(r),[])}else{sound((['ultimate','release','transformation'].includes(ab.category)?(ab.category==='ultimate'?'ultimate':'release'):'click'));toast('TÉCNICA UTILIZADA',`${ab.name} · ${(x.chargedCost??cost)>0?'−'+(x.chargedCost??cost)+' Alma':'SEM CUSTO'}`)}
 s.resources.alma.current=Number(x.alma);await window.ARQUIVO_SYNC.refresh(true);window.ARQUIVO_V3?.onActivated(s,ab,i);render();window.ARQUIVO_V3?.activationFX(s,ab);
 }catch(e){toast('Técnica não utilizada',e.message,true)}finally{rollingBusy=false;finishRollFeedback()}return}
 // Modo local: resultado não verificado e custo descontado no mesmo clique.
 let dice=[],colors=[];if(custom){dice=custom.map(d=>({sides:Number(d.sides),value:randomDie(Number(d.sides))}));colors=custom.map(d=>ABILITY_HEX.test(d.color||'')?d.color:sheetPalette(s.id).diceGroup)}else if(skill){const g=Object.keys(GROUPS).find(g=>GROUPS[g].includes(skill));const sides=[s.groups[g],window.ARQUIVO_V3?.effectiveDie(s,skill)??s.skills[skill]];dice=sides.map(n=>({sides:Number(n),value:randomDie(Number(n))}));colors=Object.values(abilityDicePalette(s,ab))}
 const result=dice.length?fichaLocalTest(s,dice):null;if(result&&skill)window.ARQUIVO_V3?.consumeNext(s,skill);window.ARQUIVO_V3?.useLocally(s,ab);window.ARQUIVO_V3?.commitLocalCharge(s,ab,i,quote);if(result&&result.dice.length>dice.length)colors.push('#E8C56D');s.resources.alma.current-=cost;if(s.resources.alma.current===0){s.combat??={};s.combat.almaExhaustion=true;s.conditions??=[];if(!s.conditions.some(c=>String(c).toLowerCase()==='desmaiado'))s.conditions.push('Desmaiado')}if(item&&inventoryItemHasQuantity(item))item.quantity=Number(item.quantity)-1;save();window.ARQUIVO_V3?.onActivated(s,ab,i);if(result){const {total,special}=result;dice=result.dice;const r={label:ab.name,total,special,dice,colors,effect:result.effect,summary:formatRollEffect(result,false)};lastRoll=r;rollHistory.unshift(r);showRollImpact(special);sound((['ultimate','release','transformation'].includes(ab.category)?(ab.category==='ultimate'?'ultimate':'release'):'dice'));render();window.ARQUIVO_V3?.activationFX(s,ab);modal('TÉCNICA · RESULTADO LOCAL',rollStage(r),[])}else{sound((['ultimate','release','transformation'].includes(ab.category)?(ab.category==='ultimate'?'ultimate':'release'):'click'));toast('TÉCNICA UTILIZADA',`${ab.name} · ${cost>0?'−'+cost+' Alma':'SEM CUSTO'}`);render();window.ARQUIVO_V3?.activationFX(s,ab)}finishRollFeedback()}
function restDialog(){if(!sheetPermission())return;if(!requirePlayer())return;const s=db.sheets.find(x=>x.id===currentSheet);modal('RECUPERAÇÃO',`<p>Descanso breve: 2 dados de Corpo e Mente, 1 de Espírito. Completo: 4, 4 e 2. A atividade escolhida acrescenta 1 dado ao recurso correspondente.</p><p>Descansos breves usados neste ciclo: ${Number(s.restCount)||0} / 2.</p><div class="field"><label>Exposição reduzida pelo descanso breve<select id="restExposure">${Object.entries(s.exposures||{}).filter(([k,v])=>Number(v)>0).map(([k,v])=>`<option value="${esc(k)}">${esc(k)} · nível ${v}</option>`).join('')}<option value="">${Object.values(s.exposures||{}).some(v=>v>0)?'Reduzir a primeira disponível':'Sem exposição acumulada'}</option></select></label></div><div class="field"><label>Atividade</label><select id="restActivity"><option value="vida">Tratamento · Vida</option><option value="estabilidade">Recomposição · Estabilidade</option><option value="alma">Meditação · Alma</option></select></div><p class="subtitle">O mestre decide se a cena oferece tempo e segurança para descansar.</p>`,[['BREVE','restShort','main'],['COMPLETO','restFull'],['Cancelar','closeModal']])}
function rest(kind){if(!sheetPermission())return;if(!requirePlayer())return;const s=db.sheets.find(x=>x.id===currentSheet),activity=el('restActivity')?.value;if(!s)return;if(kind==='breve'&&(Number(s.restCount)||0)>=2){toast('Limite atingido','Realize um descanso completo antes de obter benefícios de outro breve.',true);return}const base=kind==='breve'?{vida:2,estabilidade:2,alma:1}:{vida:4,estabilidade:4,alma:2};const oldResources=Object.fromEntries(['vida','estabilidade','alma'].map(k=>[k,Number(s.resources[k]?.current)||0]));const result=[];for(const [k,g] of Object.entries({vida:'Corpo',estabilidade:'Mente',alma:'Espírito'})){let sides=Number(s.groups[g])||4;if(kind==='breve'&&Number(s.restCount)===1)sides=stepDown(sides);const count=base[k]+(k===activity?1:0),rolls=Array.from({length:count},()=>randomDie(sides)),total=rolls.reduce((a,b)=>a+b,0),before=s.resources[k].current;s.resources[k].current=before>s.resources[k].max?before:Math.min(s.resources[k].max,before+total);result.push(`${k}: ${count}d${sides} [${rolls.join(', ')}] → +${s.resources[k].current-before}`)}reconcileRecoveryStates(s,oldResources);if(kind==='breve'){s.restCount=(Number(s.restCount)||0)+1;s.desgaste=Math.max(0,(s.desgaste||0)-2);if(s.exposures){const chosen=el('restExposure')?.value||Object.keys(s.exposures).find(k=>Number(s.exposures[k])>0);if(chosen&&Number(s.exposures[chosen])>0)s.exposures[chosen]--}}else{s.restCount=0;s.desgaste=0;s.exposures={}}save();closeModal();render();toast('DESCANSO '+kind.toUpperCase(),result.join(' · '));sound('click')}
function addCondition(){if(!sheetPermission()||!requirePlayer())return;modal('ADICIONAR ESTADO OU CONDIÇÃO',`<div class="field"><label>Condições do sistema<select id="conditionPreset"><option value="">Escolha uma condição…</option>${CONDITIONS_CATALOG.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}<option value="__custom">Outra condição (personalizada)</option></select></label></div><div class="field"><label>Condição personalizada<input id="conditionName" placeholder="Digite apenas para condição extra" maxlength="70"></label></div>`,[['ADICIONAR','confirmCondition','main'],['Cancelar','closeModal']])}
function confirmCondition(){if(!sheetPermission())return;const preset=el('conditionPreset')?.value||'',custom=el('conditionName')?.value.trim()||'';const str=preset&&preset!=='__custom'?preset:custom;if(!str||str.length>70){toast('Condição inválida','Escolha uma condição ou digite uma condição extra de até 70 caracteres.',true);return}const s=db.sheets.find(x=>x.id===currentSheet);s.conditions??=[];if(!s.conditions.includes(str))s.conditions.push(str);if(str.toLowerCase()==='amedrontado'){s.combat??={};const steps=[6,8,10,12],old=Number(s.combat.fearDie)||0;s.combat.fearDie=old?steps[Math.min(3,Math.max(0,steps.indexOf(old))+1)]:6}if(str.toLowerCase()==='pressionado'){s.combat??={};s.combat.pressuredUntil=Math.max(Number(s.combat.pressuredUntil)||0,(Number(s.combat.round)||1)+1)}save();closeModal();render()}
function removeCondition(i){if(!sheetPermission())return;if(!requirePlayer())return;const s=db.sheets.find(x=>x.id===currentSheet);const removed=s.conditions?.splice(i,1)?.[0];if(String(removed||'').toLowerCase()==='amedrontado'&&s.combat)s.combat.fearDie=0;if(String(removed||'').toLowerCase()==='pressionado'&&s.combat)s.combat.pressuredUntil=0;save();render()}
function editNotes(){if(!sheetPermission())return;const s=db.sheets.find(x=>x.id===currentSheet);modal('EDITAR NOTAS',`<div class="field"><label>Notas do personagem</label><textarea rows="10" id="notesField">${esc(s.notes||'')}</textarea></div><div class="sheet-toolbar"><label>Cor do trecho <input type="color" id="noteColorPicker" value="#FF7A1A"></label>${btn('COLORIR SELEÇÃO','colorNote','small')}</div><p class="color-hint">Selecione o texto antes de clicar em Colorir. **negrito** também funciona.</p>`,[['SALVAR','saveNotes','main'],['Cancelar','closeModal']])}
