function picker(field,label,value){return `<label>${esc(label)}<select data-edit="${esc(field)}">${VALID_DICE.map(d=>`<option value="${d}" ${Number(value)===d?'selected':''}>d${d}</option>`).join('')}</select></label>`}
let pendingSheetImage=null,pendingAbilityImages=new WeakMap(),sheetFormSaving=false,mediaUploadsInFlight=0;function openSheetForm(id,onlyMaster=false,scope='all'){pendingSheetImage=null;pendingAbilityImages=new WeakMap();editorScope=scope;editorAbilityOnly=null;editorDraft=clone((id&&db.sheets.find(s=>s.id===id))||blankSheet());if(!id)editorDraft.masterOnly=!!onlyMaster;drawSheetForm()}
function drawSheetForm(){const s=editorDraft;modal('EDITOR DE FICHA',`<div class="sheet-form"><div class="sheet-edit-scroll"><h3>IDENTIDADE</h3><label>Nome<input data-edit="name" value="${esc(s.name)}"></label><label>Subtítulo<input data-edit="subtitle" value="${esc(s.subtitle||'')}"></label><label>Raça<select data-edit="race"><option value="">Não definida</option>${['Shinigami','Visored','Hollow','Arrancar','Quincy','Humano','Fullbringer'].map(r=>`<option value="${r}" ${s.race===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Nível<input type="number" min="1" data-edit="level" value="${s.level}"></label><label>Imagem / GIF até 15 MB<input type="file" id="formImage" accept="image/gif,image/png,image/jpeg,image/webp"></label><label>Ou link direto da imagem<input data-edit="image" type="url" placeholder="https://..." value="${esc(/^https?:\/\//i.test(s.image||'')?s.image:'')}"></label><label class="${master()?'':'hidden'}">Jogador responsável<select data-edit="ownerKeyId"><option value="">Sem responsável</option>${db.keys.filter(k=>k.kind==='player').map(k=>`<option value="${esc(k.id)}" ${s.ownerKeyId===k.id?'selected':''}>${esc(k.name)}</option>`).join('')}</select></label>${master()?`<label class="private-sheet-setting"><input type="checkbox" data-edit="masterOnly" ${s.masterOnly?'checked':''}> <b>FICHA EXCLUSIVA DO MESTRE</b><small>Aparece apenas na seção reservada aos mestres dentro de Fichas; jogadores e visitantes não conseguem acessar os dados nem as rolagens.</small></label><label class="private-sheet-setting"><input type="checkbox" data-edit="locked" ${s.locked?'checked':''}> <b>TRAVAR FICHA</b><small>Somente o mestre e jogadores associados podem ver o conteúdo. Para os demais, aparece FICHA DESCONHECIDA.</small></label>`:''}${!master()&&role==='player'?`<label class="private-sheet-setting"><input type="checkbox" data-edit="locked" ${s.locked?'checked':''}> <b>TRAVAR FICHA</b><small>Ativada por padrão. Apenas jogadores vinculados e o mestre poderão visualizar fichas trancadas.</small></label>`:''}<h3>GRUPOS</h3><div class="form-grid">${Object.keys(GROUPS).map(g=>picker('groups.'+g,g,s.groups[g])).join('')}</div><h3>PERÍCIAS</h3>${Object.entries(GROUPS).map(([g,skills])=>`<h4>${g} ${btn('COPIAR DADO DO GRUPO','applyGroup:'+g,'small')}</h4><div class="form-grid">${skills.map(sk=>picker('skills.'+sk,sk,s.skills[sk])).join('')}</div>`).join('')}<h3>RECURSOS MÁXIMOS</h3><div class="form-grid">${['vida','estabilidade','alma'].map(k=>`<label>${k}<input type="number" min="0" data-edit="resources.${k}.max" value="${s.resources[k].max}"></label>`).join('')}</div><h3>HABILIDADES</h3><p class="color-hint">Modelo: NOME | CUSTO OU TIPO. Descreva o efeito, quando funciona e seus limites. Custo zero é SEM CUSTO; somente habilidades passivas são inativáveis.</p>${s.abilities.map((ab,i)=>`<div class="ability-edit"><label>Nome<input data-ability="${i}:name" value="${esc(ab.name)}"></label><label>Tipo de habilidade<select data-ability="${i}:category">${[['active','ATIVA'],['passive','PASSIVA'],['mechanic','MECÂNICA'],['release','LIBERAÇÃO'],['transformation','TRANSFORMAÇÃO'],['ultimate','ULTIMATE'],['item','ITEM']].map(([value,label])=>`<option value="${value}" ${abilityCategory(ab)===value?'selected':''}>${label}</option>`).join('')}</select></label>${abilityCategory(ab)==='item'?`<label>Item do inventário<select data-ability="${i}:inventoryItemId"><option value="">Sem vínculo</option>${(s.inventory?.items||[]).map(it=>`<option value="${esc(it.id||'')}" ${ab.inventoryItemId===it.id?'selected':''}>${esc(it.name||'Item')}${inventoryItemHasQuantity(it)?' (×'+esc(it.quantity)+')':' (sem limite)'}</option>`).join('')}${ab.inventoryItemId&&!(s.inventory?.items||[]).some(it=>it.id===ab.inventoryItemId)?`<option value="${esc(ab.inventoryItemId)}" selected>Item não encontrado</option>`:''}</select><small>Ao usar, consome 1 unidade se o item tiver quantidade definida.</small></label>`:''}<label>Custo de Alma<input type="number" min="0" data-ability="${i}:cost" value="${ab.cost}" ${abilityCategory(ab)==='passive'?'disabled':''}></label><div class="ability-flag"><label><input type="checkbox" data-ability="${i}:noTest" ${ab.noTest?'checked':''} ${abilityCategory(ab)==='passive'?'disabled':''}> Sem teste</label></div><label>Descrição (aceita [cor=#FF7A1A]texto[/cor])<textarea data-ability="${i}:description" placeholder="Quando se aplica, o que acontece e quais são os limites.">${esc(ab.description||'')}</textarea></label><div class="ability-color-editor" ${ab.noTest||abilityCategory(ab)==='passive'?'hidden':''}><label>Perícia do teste (opcional)<select data-ability="${i}:testSkill"><option value="">Sem teste definido</option>${Object.entries(GROUPS).map(([group,skills])=>`<optgroup label="${esc(group)}">${skills.map(skill=>`<option value="${esc(skill)}" ${abilityTestSkill(ab)===skill?'selected':''}>${esc(skill)}</option>`).join('')}</optgroup>`).join('')}</select></label><label>Modo do teste<select data-ability="${i}:testMode"><option value="skill" ${!abilityCustomDice(ab)?'selected':''}>Grupo + perícia</option><option value="custom" ${abilityCustomDice(ab)?'selected':''}>Teste próprio (dados individuais)</option></select></label><p class="color-hint">Escolha grupo + perícia ou um teste próprio. O teste próprio ignora os dados de grupo/perícia, sem modificar as regras de crítico.</p>${abilityCustomDice(ab)?customDiceEditor(ab,i,s):''}<div class="form-grid"><label>Cor do dado de grupo<input type="color" data-ability="${i}:diceGroupColor" value="${abilityDicePalette(s,ab).group}"></label><label>Cor do dado de perícia<input type="color" data-ability="${i}:diceSkillColor" value="${abilityDicePalette(s,ab).skill}"></label></div>${ab.diceColors?btn('USAR CORES DA FICHA','clearAbilityColors:'+i,'small'):''}</div><label>Imagem / GIF até 15 MB<input type="file" data-ability-image="${i}" accept="image/gif,image/png,image/jpeg,image/webp"></label><label>OU LINK DIRETO DA IMAGEM<input type="url" data-ability="${i}:image" placeholder="https://..." value="${esc(/^https?:\/\//i.test(ab.image||'')?ab.image:'')}"></label>${ab.image?`<p class="color-hint">Imagem anexada ${btn('REMOVER IMAGEM','removeAbilityImage:'+i,'small danger')}</p>`:''}<div class="actions">${btn('↑','moveAbility:'+i+':-1','small')}${btn('↓','moveAbility:'+i+':1','small')}${btn('EXCLUIR','removeAbility:'+i,'small danger')}</div></div>`).join('')}${btn('+ HABILIDADE','addAbility','small')}<h3>CONDIÇÕES INICIAIS</h3><label>Separadas por vírgula<input data-edit="conditionText" value="${esc((s.conditions||[]).join(', '))}"></label><h3>NOTAS</h3><label>Notas<textarea data-edit="notes" rows="5">${esc(s.notes||'')}</textarea></label><p id="sheetFormError" role="status" class="warning"></p></div><aside class="sheet-preview"><div class="preview-art" id="previewArt" style="${imgStyle(s.image)}">${s.image?'':'魂'}</div><h2 id="previewName">${esc(s.name||'Novo personagem')}</h2><p id="previewSubtitle">Nível ${s.level} · ${esc(s.subtitle||'')}</p><div id="previewResources">${['vida','estabilidade','alma'].map(k=>`<p>${k}: ${s.resources[k].max}</p>`).join('')}</div></aside></div>`,[['SALVAR','saveSheetForm','main'],['CANCELAR','cancelSheetForm']]);el('dialogRoot').querySelector('.dialog').classList.add('wide-dialog');const scroll=el('dialogRoot').querySelector('.sheet-edit-scroll');if(editorScope!=='all'&&scroll){const keep=editorScope==='skills'?['GRUPOS','PERÍCIAS']:editorScope==='identity'?['IDENTIDADE']:editorScope==='resources'?['RECURSOS MÁXIMOS']:editorScope==='abilities'?['HABILIDADES']:editorScope==='conditions'?['CONDIÇÕES INICIAIS']:['NOTAS'];let visible=false;for(const child of scroll.children){if(child.tagName==='H3')visible=keep.includes(child.textContent.trim());if(child.id==='sheetFormError')visible=true;if(!visible)child.classList.add('hidden')}if(editorScope==='abilities'&&editorAbilityOnly!==null)scroll.querySelectorAll('.ability-edit').forEach((node,i)=>node.classList.toggle('hidden',i!==editorAbilityOnly));el('dialogRoot').querySelector('.dialog h2').textContent='EDITOR · '+editorScope.toUpperCase()}window.ARQUIVO_V3?.enhanceEditor()}
function updateDraft(target){const f=target.dataset.edit;if(f){const value=(f==='locked'||f==='masterOnly')?target.checked:target.value;if(f==='conditionText')editorDraft.conditions=value.split(',').map(x=>x.trim()).filter(Boolean);else{const parts=f.split('.');let o=editorDraft;for(let i=0;i<parts.length-1;i++)o=o[parts[i]];o[parts.at(-1)]=f==='level'||f.startsWith('groups.')||f.startsWith('skills.')||f.startsWith('resources.')?Number(value):value}}if(target.dataset.ability){const [i,k]=target.dataset.ability.split(':');const ab=editorDraft.abilities[+i];if(k==='category'){ab.category=target.value;ab.passive=target.value==='passive';if(target.value!=='item')ab.inventoryItemId='';if(ab.passive){ab.cost=0;ab.noTest=true}drawSheetForm();return}if(k==='noTest'){ab.noTest=target.checked;drawSheetForm();return}if(k==='testMode'){if(target.value==='custom')ab.testDice=Array.isArray(ab.testDice)&&ab.testDice.length?ab.testDice:[{sides:4,color:sheetPalette(editorDraft.id).diceGroup}];else ab.testDice=[];drawSheetForm();return}if(k==='diceGroupColor'||k==='diceSkillColor'){ab.diceColors??={};ab.diceColors[k==='diceGroupColor'?'group':'skill']=target.value}else ab[k]=k==='cost'?Number(target.value):target.value}if(target.dataset.abilityDie){const [i,j,key]=target.dataset.abilityDie.split(':');const d=editorDraft.abilities[+i]?.testDice?.[+j];if(d)d[key]=key==='sides'?Number(target.value):target.value}el('previewName').textContent=editorDraft.name||'Novo personagem';el('previewSubtitle').textContent='Nível '+editorDraft.level+' · '+editorDraft.subtitle;el('previewResources').innerHTML=['vida','estabilidade','alma'].map(k=>`<p>${k}: ${editorDraft.resources[k].max}</p>`).join('')}
function applyGroup(g){for(const sk of GROUPS[g])editorDraft.skills[sk]=editorDraft.groups[g];drawSheetForm()}
function addAbility(){editorDraft.abilities.push({name:'',category:'active',passive:false,noTest:false,cost:0,description:''});if(editorScope==='abilities')editorAbilityOnly=editorDraft.abilities.length-1;drawSheetForm()}
function removeAbility(i){editorDraft.abilities.splice(i,1);editorAbilityOnly=null;drawSheetForm()}
function addAbilityDie(i){const ab=editorDraft?.abilities?.[i];if(!ab)return;ab.testDice??=[];if(ab.testDice.length>=12){toast('Limite de dados','No máximo 12 dados por teste.',true);return}ab.testDice.push({sides:4,color:sheetPalette(editorDraft.id).diceGroup});drawSheetForm()}
function removeAbilityDie(i,j){editorDraft?.abilities?.[i]?.testDice?.splice(j,1);drawSheetForm()}
function moveAbility(i,d){const j=i+d;if(j<0||j>=editorDraft.abilities.length)return;[editorDraft.abilities[i],editorDraft.abilities[j]]=[editorDraft.abilities[j],editorDraft.abilities[i]];drawSheetForm()}
function cancelSheetForm(){confirmSite('DESCARTAR ALTERAÇÕES','Sair sem salvar a ficha?',()=>{editorDraft=null;closeModal()})}
async function saveSheetForm(){
 if(!requirePlayer()||sheetFormSaving)return;
 if(mediaUploadsInFlight){toast('Envio em andamento','Conclua o envio da imagem antes de salvar a ficha.',true);return}
 sheetFormSaving=true;
 try{
  const raw=clone(editorDraft),old=db.sheets.find(s=>s.id===raw.id),st=window.ARQUIVO_SYNC;
  const queued=editorDraft.abilities.map((ab,i)=>({i,file:pendingAbilityImages.get(ab)})).filter(x=>x.file);
  const hasUploads=!!pendingSheetImage||queued.length>0;
  for(const k of ['vida','estabilidade','alma'])raw.resources[k].current=old?old.resources[k].current:raw.resources[k].max;
  let sheet=validateSheet(raw,1);
  if(!master()){
   if(old?.masterOnly)throw Error('Ficha exclusiva do mestre.');
   sheet.masterOnly=false;
   sheet.locked=raw.locked!==false;
   if(db.sheets.some(x=>x.id===sheet.id)&&!canEditSheet(sheet.id))throw Error('Você não pode alterar a ficha de outro jogador.');
   sheet.ownerKeyId=old?.ownerKeyId||keyOwnerId;sheet.linkedKeyIds=old?linkedIds(old):[keyOwnerId];
  }else{sheet.ownerKeyId=raw.ownerKeyId||'';sheet.linkedKeyIds=linkedIds(sheet);if(sheet.ownerKeyId&&!sheet.linkedKeyIds.includes(sheet.ownerKeyId))sheet.linkedKeyIds.push(sheet.ownerKeyId)}
  if(hasUploads){
   if(!st?.state.enabled)throw Error('Conecte-se ao Supabase para salvar anexos de até 15 MB.');
   if(!old){
    if(master()){
     db.sheets.push(sheet);
     save();
     await st.state.pending;
     const confirmation=await st.state.client.rpc('ae_read_document');
     if(confirmation.error||!confirmation.data?.data?.sheets?.some(x=>x.id===sheet.id))throw Error('A ficha não foi registrada no servidor antes do envio.');
    }else sheet=await st.saveOwnedSheet(sheet);
    editorDraft.id=sheet.id;
   }
   if(pendingSheetImage)sheet.image=await st.uploadSheetMedia(sheet.id,pendingSheetImage);
   for(const entry of queued)sheet.abilities[entry.i].image=await st.uploadSheetMedia(sheet.id,entry.file);
  }
  if(!master()&&st?.state.enabled)sheet=await st.saveOwnedSheet(sheet);
  const i=db.sheets.findIndex(s=>s.id===sheet.id);
  if(i>=0)db.sheets[i]=sheet;else db.sheets.push(sheet);
  if(master()&&sheet.ownerKeyId){
   const key=db.keys.find(k=>k.id===sheet.ownerKeyId&&k.kind==='player');
   if(key)key.sheetId=sheet.id;
  }
  if(master())save();
  else if(st?.state.enabled)await st.refresh(true);
  else DATASTORE.save(db);
  pendingSheetImage=null;pendingAbilityImages=new WeakMap();editorDraft=null;editorScope='all';editorAbilityOnly=null;
  closeModal();page='sheets';currentSheet=sheet.id;render();toast('Ficha salva',sheet.name);
 }catch(e){const node=el('sheetFormError');if(node)node.textContent=e.message;toast('Ficha não concluída',e.message,true)}
 finally{sheetFormSaving=false}
}
async function imageForForm(input){const file=input.files?.[0];if(!file)return;try{acceptedImage(file);if(!editorDraft?.id||!db.sheets.some(s=>s.id===editorDraft.id)){pendingSheetImage=file;const elPreview=el('previewArt');if(elPreview){elPreview.style.backgroundImage='url('+URL.createObjectURL(file)+')';elPreview.textContent=''}toast('GIF preparado','Será enviado quando você salvar a nova ficha.');return}mediaUploadsInFlight++;let ref;try{ref=await window.ARQUIVO_SYNC.uploadSheetMedia(editorDraft.id,file)}finally{mediaUploadsInFlight--}editorDraft.image=ref;const node=el('previewArt');if(node){node.style.backgroundImage='url('+URL.createObjectURL(file)+')';node.textContent=''}toast('Arquivo enviado','Salve a ficha para vincular o novo anexo.')}catch(e){toast('Erro na imagem',e.message,true)}}

